preg_match('/name="balance_token" value="([a-f0-9]+)"/',$html,$m);lft_assert(!empty($m[1]),'Confirmation token absent');$apply=['id'=>$id,'version'=>$version,'action'=>'savings_apply','identity'=>'212200001','balance_token'=>$m[1],'csrf_token'=>str_repeat('a',64)];
