$post['version']=$version+1;$post['csrf_token']='invalid';lft_assert(review_http($sid,$query,$post)[0]===403,'CSRF accepted');
$post['csrf_token']=str_repeat('a',64);$post['amount']='-1';lft_assert(review_http($sid,$query,$post)[0]===409,'Negative FIX accepted');
$post['amount']='1.001';lft_assert(review_http($sid,$query,$post)[0]===409,'Overprecision FIX accepted');
lft_assert(in_array(review_http('', $query)[0],[302,403],true),'Anonymous access accepted');
foreach(['admin','kasir','bendahara'] as $role){$a=lf_one($koneksi,'SELECT id,unit_id FROM admin WHERE role=? AND is_active=1 LIMIT 1',[$role]);if($a)lft_assert(in_array(review_http(review_session($a['id'],$role,(int)$a['unit_id']),$query)[0],[302,403],true),'Role accepted '.$role);}
lft_assert(in_array(review_http(review_session($actor,'super_admin',$unit===3?2:3),$query)[0],[403,409],true),'Cross-unit access accepted');
$all=review_session($actor,'super_admin',0);lft_assert(review_http($all,$query)[0]===200,'All-unit read denied');$post['amount']='900';lft_assert(review_http($all,$query,$post)[0]===409,'All-unit mutation accepted');
$post['version']=(int)lful_draft($id)['version'];$post['amount']='1000';[$status,$html]=review_http($sid,$query,$post);preg_match('/name="balance_token" value="([a-f0-9]+)"/',$html,$expired);session_id($sid);session_start();$_SESSION['lop_balance_confirmation'][$id]['212200001']['expires']=0;session_write_close();$expiredApply=$apply;$expiredApply['version']=$post['version'];$expiredApply['balance_token']=$expired[1];lft_assert(review_http($sid,$query,$expiredApply)[0]===409,'Expired balance confirmation accepted');
$name='review_inactive_'.bin2hex(random_bytes(6));lf_query($koneksi,"INSERT INTO admin(username,password,nama,role,unit_id,is_active) SELECT ?,password,'Inactive QA',role,unit_id,0 FROM admin WHERE id=?",[$name,$actor]);$inactive=(int)$koneksi->insert_id;try{lft_assert(in_array(review_http(review_session($inactive,'super_admin',$unit),$query)[0],[302,403],true),'Inactive account accepted');}finally{lf_query($koneksi,'DELETE FROM admin WHERE id=?',[$inactive]);}
$curl=curl_init($base.'/legacy_import_api.php?'.http_build_query(['action'=>'full_status','id'=>$id]));curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>'PHPSESSID='.$sid]);$body=curl_exec($curl);$status=curl_getinfo($curl,CURLINFO_RESPONSE_CODE);curl_close($curl);$statusData=json_decode($body,true);lft_assert($status===200&&isset($statusData['draft'],$statusData['catalog'],$statusData['operational_review']['banks']),'Status API compatibility or metadata missing');
